// ===== n8n Code node — "Run Once for All Items" =====
const MAX_CHARS = 2000;   // upper bound per chunk
const MIN_CHARS = 60;     // below this, a block gets merged into its neighbour
const SUBJECT = "جغرافيا - عالم الشمال والجنوب";   // TODO: feed from a Set node for subject #2

// ---------- normalisation (NOTE: <br/> is handled per-cell, never globally) ----------
function normalise(text) {
  return text
    .replace(/@aliwehbedu/g, '')
    .replace(/CamScanner/gi, '')
    .replace(/[ \t]+\n/g, '\n')
    .trim();
}

// ---------- table helpers ----------
const isTableLine = l => l.trim().startsWith('|');

// positional split — empty cells are KEPT so columns stay aligned with their headers
function cellsOf(line) {
  const parts = line.split('|');
  if (parts[0].trim() === '') parts.shift();
  if (parts.length && parts[parts.length - 1].trim() === '') parts.pop();
  return parts.map(c =>
    c.trim().replace(/<br\s*\/?>/gi, '\n').replace(/&#xA;/g, '\n').trim());
}

function isSeparatorLine(line) {
  if (!isTableLine(line)) return false;
  const cells = cellsOf(line).filter(c => c !== '');
  return cells.length > 0 && cells.every(c => /^:?-{2,}:?$/.test(c));
}

// a header row is only believable if its cells are short, label-like strings
function isPlausibleHeader(cells) {
  const filled = cells.filter(c => c !== '');
  return filled.length > 0 && filled.every(c => c.length <= 40 && !/\n/.test(c));
}

// LlamaParse sometimes jams a whole second table into one cell as tab-separated text
function extractJammedTables(cellText) {
  if (!cellText.includes('\t')) return null;
  const marker = cellText.indexOf('---');
  const residual = marker === -1 ? '' : cellText.slice(0, marker).trim();
  const blob = marker === -1 ? cellText : cellText.slice(marker + 3);
  const parts = blob.split('\t');
  if (parts.length < 3) return null;
  const nl = parts[1].indexOf('\n');
  if (nl === -1) return null;
  return {
    residual,
    docs: [
      { title: parts[0].trim(), body: parts[1].slice(nl + 1).trim() },
      { title: parts[1].slice(0, nl).trim(), body: parts.slice(2).join('\t').trim() },
    ],
  };
}

const splitNumberedInline = text => {
  const p = text.split(/(?=(?:^|\s)\d+-\s)/g).map(x => x.trim()).filter(Boolean);
  return p.length > 1 ? p : [text];
};


// ---------- HTML tables (LlamaParse emits these instead of pipes on some runs) ----------
const hasHtmlTable = s => /<table[\s>]/i.test(s) || /<t[dr][\s>]/i.test(s);

function htmlToText(html) {
  return html
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|li|tr)>/gi, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<').replace(/&gt;/gi, '>')
    .replace(/&#xA;/gi, '\n').replace(/&quot;/gi, '"')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .split('\n').map(l => l.trim()).join('\n')
    .trim();
}

function parseHtmlTables(section) {
  const cells = [];                       // {label, text}
  // Split on OPENING tags instead of matching open/close pairs, so a table that was
  // truncated mid-way (its </table>, </tr>, </td> cut off by a --- separator) still parses.
  const tables = section.split(/<table[^>]*>/i).slice(1);
  tables.forEach(tbl => {
    let header = null;
    tbl.split(/<tr[^>]*>/i).slice(1).forEach(tr => {
      const isHeaderRow = /<th[^>]*>/i.test(tr);
      const parts = tr.split(/<t[dh][^>]*>/i).slice(1);
      const texts = parts
        .map(p => htmlToText(p.replace(/<\/t[dh]>[\s\S]*$/i, '')))
        .map(t => t.trim());
      if (!texts.length) return;
      if (isHeaderRow) { header = texts; return; }
      texts.forEach((text, ci) => {
        if (!text || text === '-' || text.replace(/\s/g, '').length < 3) return;
        if (text.length < 25 && !/\d/.test(text)) return;   // bare row-label cell, no content
        cells.push({ label: header ? (header[ci] || '') : '', text });   // one record PER CELL
      });
    });
  });
  return cells;
}

// a whole HTML table cell is usually several numbered topics — split them apart
function splitNumberedBlock(text) {
  const p = text.split(/(?=^\s*\*?\*?\d+-\s)/m).map(x => x.trim()).filter(Boolean);
  return p.length > 1 ? p : [text];
}

// ---------- parsers ----------
function parseTableSection(section, title) {
  const lines = section.split('\n').filter(isTableLine);
  const rowsRaw = [], extraDocs = [];
  let header = null, pendingHeaderLine = null;

  for (let i = 0; i < lines.length; i++) {
    if (isSeparatorLine(lines[i])) {
      const cand = pendingHeaderLine ? cellsOf(pendingHeaderLine) : null;
      if (cand && isPlausibleHeader(cand)) header = cand;
      else { header = null; if (cand) rowsRaw.push({ cells: cand, header: null }); } // was data, not a header
      pendingHeaderLine = null;
      continue;
    }
    if (i + 1 < lines.length && isSeparatorLine(lines[i + 1])) { pendingHeaderLine = lines[i]; continue; }
    rowsRaw.push({ cells: cellsOf(lines[i]), header });
  }

  const rows = rowsRaw.map(r => ({
    header: r.header,
    cells: r.cells.map(c => {
      const jam = extractJammedTables(c);
      if (!jam) return c;
      jam.docs.forEach(d => extraDocs.push(d));
      return jam.residual;
    }),
  }));

  const blocks = rows.map(r =>
    r.cells.map((cell, ci) => {
      if (cell === '' || cell === '-') return null;         // skip empty / placeholder cells
      const label = r.header ? (r.header[ci] || '') : '';
      return label ? `${label}: ${cell}` : cell;
    }).filter(Boolean).join('\n\n')
  ).filter(t => t.replace(/\s/g, '').length > 3);

  return { blocks, extraDocs, title };
}

function parseProseSection(section) {
  let title = '';
  const kept = [];
  section.split('\n').forEach(l => {
    const m = l.match(/^#{1,6}\s+(.*)$/);
    if (m && !title) { title = m[1].trim(); return; }   // h1 = context, not its own chunk
    kept.push(l);
  });
  const blocks = kept.join('\n').trim()
    .split(/(?=^#{2,3}\s|^\*\*-?\d+[-–.]\s|^\d+-\s)/gm)
    .map(p => p.trim()).filter(Boolean);
  return { blocks, title };
}

// ---------- sizing ----------
function splitOversized(text) {
  if (text.length <= MAX_CHARS) return [text];
  const subParts = text.split(/(?=[أ-ي]-\s)/g).map(p => p.trim()).filter(Boolean);
  if (subParts.length <= 1) {
    const out = [];
    for (let i = 0; i < text.length; i += MAX_CHARS) out.push(text.slice(i, i + MAX_CHARS));
    return out;
  }
  const grouped = []; let buf = '';
  for (const p of subParts) {
    if (buf && (buf + '\n' + p).length > MAX_CHARS) { grouped.push(buf.trim()); buf = p; }
    else buf = buf ? buf + '\n' + p : p;
  }
  if (buf) grouped.push(buf.trim());
  return grouped;
}

function mergeTiny(blocks) {
  const out = [];
  for (const b of blocks) {
    if (out.length && (b.length < MIN_CHARS || out[out.length - 1].length < MIN_CHARS))
      out[out.length - 1] += '\n\n' + b;
    else out.push(b);
  }
  return out;
}

// ---------- main ----------
const input = $input.all()[0].json;
const cleaned = normalise(input.markdown || input.text || '');
const sections = cleaned.split(/\n-{3,}\n/).map(s => s.trim()).filter(Boolean);

const records = [];
sections.forEach((section, si) => {
  const hasTable = section.split('\n').some(isSeparatorLine);
  const headingsAll = [...section.matchAll(/^#{1,6}\s+(.*)$/gm)].map(m => m[1].trim());

  if (!hasTable && hasHtmlTable(section)) {
    parseHtmlTables(section).forEach(cell => {
      splitNumberedBlock(cell.text).forEach(b =>
        records.push({
          section: si,
          title: headingsAll[0] || '',
          // the column label is repeated on EVERY block so a chunk can never lose
          // track of which column (عالم الشمال / عالم الجنوب) it belongs to
          text: cell.label ? `${cell.label}\n\n${b}` : b,
          type: 'html_table_cell',
        }));
    });
    // GUARD: a section that had real content must never vanish silently
    if (!records.some(r => r.section === si) && section.replace(/<[^>]+>|\s/g, '').length > 40) {
      records.push({ section: si, title: headingsAll[0] || '', text: htmlToText(section), type: 'html_fallback' });
    }
    return;
  }

  if (hasTable) {
    const headings = [...section.matchAll(/^#{1,6}\s+(.*)$/gm)].map(m => m[1].trim());
    const extraDocs = [];

    if (headings.length > 1) {
      // section holds several titled tables — title each one separately
      section.split(/^#{1,6}\s+.*$/gm).filter(p => p.trim()).forEach((part, pi) => {
        const sub = parseTableSection(part, headings[pi] || '');
        sub.blocks.forEach(b => records.push({ section: si, title: headings[pi] || '', text: b, type: 'table_row' }));
        sub.extraDocs.forEach(d => extraDocs.push(d));
      });
    } else {
      const r = parseTableSection(section, headings[0] || '');
      r.blocks.forEach(b => records.push({ section: si, title: headings[0] || '', text: b, type: 'table_row' }));
      r.extraDocs.forEach(d => extraDocs.push(d));
    }

    extraDocs.forEach(d =>
      splitNumberedInline(d.body).forEach(b =>
        records.push({ section: si, title: d.title, text: b, type: 'table_row' })));
  } else {
    const r = parseProseSection(section);
    mergeTiny(r.blocks).forEach(b =>
      records.push({ section: si, title: r.title, text: b, type: 'prose_block' }));
  }
});

const final = [];
records.forEach(r => splitOversized(r.text).forEach(t =>
  final.push({ ...r, text: r.title ? `${r.title}\n\n${t}` : t })));

return final
  .filter(c => c.text.replace(/\s/g, '').length > 8)
  .map((c, i) => ({
    json: {
      chunk_id: `${SUBJECT.replace(/\s+/g, '_')}-${c.section}-${i}`,
      subject: SUBJECT,
      section_index: c.section,
      heading: c.title,
      chunk_type: c.type,
      text: c.text,
      char_count: c.text.length,
    },
  }));
